create or replace function public.get_organization_category_analytics(p_org uuid) returns table(category_id uuid,category_name text,event_name text,total_votes bigint,paid_votes bigint,gross_minor bigint) language sql stable security definer set search_path='' as $$ select c.id,c.name,e.name,coalesce(sum(b.quantity),0)::bigint,coalesce(sum(case when b.payment_attempt_id is null then 0 else b.quantity end),0)::bigint,coalesce(sum(case when l.status in ('confirmed','refunded','reversed') then l.gross_amount_minor-l.refunded_amount_minor else 0 end),0)::bigint from public.categories c join public.events e on e.id=c.event_id left join public.vote_batches b on b.category_id=c.id left join public.payment_attempts p on p.id=b.payment_attempt_id left join public.paid_vote_ledger l on l.reference=p.provider_reference where e.organization_id=p_org and private.is_org_member(p_org) group by c.id,c.name,e.name order by 4 desc; $$;
revoke all on function public.get_organization_category_analytics(uuid) from public,anon; grant execute on function public.get_organization_category_analytics(uuid) to authenticated;
create or replace function private.notify_high_risk_flag() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.severity>=4 then insert into public.notifications(user_id,organization_id,kind,title,body) select m.user_id,new.organization_id,'risk_alert','High-risk activity detected','A high-severity activity flag needs your attention. Our platform team may contact you if action is required.' from public.organization_members m where m.organization_id=new.organization_id; end if; return new; end $$;
drop trigger if exists high_risk_flag_notification on public.moderation_flags;
create trigger high_risk_flag_notification after insert on public.moderation_flags for each row execute function private.notify_high_risk_flag();

